import "primereact/resources/themes/lara-light-indigo/theme.css";  // Theme
import "primereact/resources/primereact.min.css";  // Core styles
import "primeicons/primeicons.css";  // PrimeIcons
import React, { useState, useEffect, useRef } from "react";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { Button } from "primereact/button";
import { Toast } from "primereact/toast";
import { Dialog } from "primereact/dialog";
import axios from "axios";
import { Toolbar } from "primereact/toolbar";
import "./css/VetAppointments.css";

const VetAppointments = () => {
  const clinicId = localStorage.getItem("clinicId");
  const [appointments, setAppointments] = useState([]);
  const [selectedAppointment, setSelectedAppointment] = useState(null);
  const [editDialog, setEditDialog] = useState(false);
  const [selectedAppointments, setSelectedAppointments] = useState(null);
  const toast = useRef(null);
  const dt = useRef(null);

  useEffect(() => {
    fetchAppointments();
  }, []);

  const fetchAppointments = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/appointments/clinics/${clinicId}`);
      const filteredAppointments = response.data.filter(appt => {
        const status = appt.status ? appt.status.toLowerCase() : "";
        return status === "pending" || status === "confirmed";
      });
      setAppointments(filteredAppointments);
    } catch (error) {
      toast.current.show({ severity: "error", summary: "Error", detail: "Failed to fetch appointments." });
    }
  };

  const updateAppointmentStatus = async (id, status) => {
    try {
      const updateData = { status };
      if (status === "Confirmed") {
        updateData.confirmedAt = new Date();
      } else if (status === "Completed") {
        updateData.completedAt = new Date();
      } else if (status === "Cancelled") {
        updateData.rejectedAt = new Date();
      }

      await axios.put(`http://localhost:5000/api/appointments/update/${id}`, updateData);
      toast.current.show({ severity: "success", summary: "Updated", detail: `Appointment marked as ${status}.` });
      fetchAppointments();
    } catch (error) {
      toast.current.show({ severity: "error", summary: "Error", detail: "Failed to update appointment status." });
    }
  };

  const handleEdit = (appointment) => {
    setSelectedAppointment(appointment);
    setEditDialog(true);
  };

  const handleUpdate = async () => {
    if (!selectedAppointment) return;

    try {
      await updateAppointmentStatus(selectedAppointment._id, selectedAppointment.status);
      setEditDialog(false);
    } catch (error) {
      console.error("Error updating appointment:", error);
    }
  };

  const dateTemplate = (rowData) => {
    return new Date(rowData.date).toLocaleString();
  };

  const formatStatus = (rowData) => {
    return <span className={`status-tag ${rowData.status.toLowerCase()}`}>{rowData.status.toUpperCase()}</span>;
  };

  const actionTemplate = (rowData) => {
    return (
      <div className="action-buttons">
        <Button icon="pi pi-pencil" className="p-button-warning" onClick={() => handleEdit(rowData)} />
        {rowData.status === "Pending" && (
          <>
            <Button icon="pi pi-check" className="p-button-success" onClick={() => updateAppointmentStatus(rowData._id, "Confirmed")} />
            <Button icon="pi pi-times" className="p-button-danger" onClick={() => updateAppointmentStatus(rowData._id, "Cancelled")} />
          </>
        )}
        {rowData.status === "Confirmed" && (
          <>
            <Button icon="pi pi-check" className="p-button-success" onClick={() => updateAppointmentStatus(rowData._id, "Completed")} />
            <Button icon="pi pi-times" className="p-button-danger" disabled />
          </>
        )}
      </div>
    );
  };

  const leftToolbarTemplate = () => {
    return (
      <div className="flex flex-wrap gap-2">
        <Button label="Refresh" icon="pi pi-refresh" onClick={fetchAppointments} />
      </div>
    );
  };

  const header = (
    <div className="flex align-items-center justify-content-between">
      <h4 className="m-0">Manage Appointments</h4>
    </div>
  );

  return (
    <div className="vet-appointments-container">
      <Toast ref={toast} position="bottom-right" />
      <Toolbar className="mb-4" left={leftToolbarTemplate} />
      <DataTable 
        ref={dt} 
        value={appointments} 
        selection={selectedAppointments} 
        onSelectionChange={(e) => setSelectedAppointments(e.value)}
        dataKey="_id" 
        paginator 
        rows={10} 
        rowsPerPageOptions={[5, 10, 25]}
        paginatorTemplate="FirstPageLink PrevPageLink PageLinks NextPageLink LastPageLink CurrentPageReport RowsPerPageDropdown"
        currentPageReportTemplate="Showing {first} to {last} of {totalRecords} appointments" 
        globalFilter={null} 
        header={header}
      >
        <Column selectionMode="multiple" exportable={false}></Column>
        <Column field="ownerName" header="Owner Name" sortable style={{ minWidth: '12rem' }} />
        <Column field="petDetails" header="Pet Details" sortable style={{ minWidth: '16rem' }} />
        <Column field="service_id.name" header="Service Availed" sortable style={{ minWidth: '12rem' }} />
        <Column field="date" header="Appointment Date" body={dateTemplate} sortable style={{ minWidth: '12rem' }} />
        <Column field="status" header="Status" body={formatStatus} sortable style={{ minWidth: '12rem' }} />
        <Column body={actionTemplate} exportable={false} style={{ minWidth: '12rem' }} />
      </DataTable>

      <Dialog 
        visible={editDialog} 
        header="Edit Appointment" 
        onHide={() => setEditDialog(false)} 
        className="p-fluid" 
        style={{ width: '400px' }} 
      >
        {selectedAppointment && (
          <div className="p-dialog-content">
            <div className="p-field">
              <label>Status</label>
              <select
                value={selectedAppointment.status}
                onChange={(e) => setSelectedAppointment({ ...selectedAppointment, status: e.target.value })}
              >
                {selectedAppointment.status === "Pending" && (
                  <>
                    <option value="Confirmed">Confirmed</option>
                    <option value="Cancelled">Cancelled</option>
                  </>
                )}
                {selectedAppointment.status === "Confirmed" && (
                  <option value="Completed">Completed</option>
                )}
              </select>
            </div>
          </div>
        )}
        <div className="p-dialog-footer">
          <Button label="Cancel" className="p-button-secondary" onClick={() => setEditDialog(false)} />
          <Button label="Update" className="p-button-primary" onClick={handleUpdate} />
        </div>
      </Dialog>
    </div>
  );
};

export default VetAppointments;
